using BusinessPartnerPortal.Api.Domain;
using Microsoft.EntityFrameworkCore;

namespace BusinessPartnerPortal.Api.Data;

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<User> Users => Set<User>(); public DbSet<Role> Roles => Set<Role>(); public DbSet<UserRole> UserRoles => Set<UserRole>(); public DbSet<Feature> Features => Set<Feature>(); public DbSet<Permission> Permissions => Set<Permission>(); public DbSet<RolePermission> RolePermissions => Set<RolePermission>(); public DbSet<UserPermissionOverride> UserPermissionOverrides => Set<UserPermissionOverride>();
    public DbSet<Vendor> Vendors => Set<Vendor>(); public DbSet<VendorUser> VendorUsers => Set<VendorUser>(); public DbSet<PurchaseOrder> PurchaseOrders => Set<PurchaseOrder>(); public DbSet<Grn> Grns => Set<Grn>(); public DbSet<Invoice> Invoices => Set<Invoice>(); public DbSet<InvoiceGrn> InvoiceGrns => Set<InvoiceGrn>(); public DbSet<Document> Documents => Set<Document>(); public DbSet<InvoiceStatusHistory> InvoiceStatusHistory => Set<InvoiceStatusHistory>(); public DbSet<Payment> Payments => Set<Payment>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<User>(e=>{e.ToTable("users","security");e.HasKey(x=>x.Id);e.Property(x=>x.Id).HasColumnName("id");e.Property(x=>x.FullName).HasColumnName("full_name");e.Property(x=>x.Email).HasColumnName("email");e.Property(x=>x.PasswordHash).HasColumnName("password_hash");e.Property(x=>x.UserType).HasColumnName("user_type");e.Property(x=>x.DepartmentId).HasColumnName("department_id");e.Property(x=>x.IsSuperAdmin).HasColumnName("is_super_admin");e.Property(x=>x.IsActive).HasColumnName("is_active");e.Property(x=>x.MfaEnabled).HasColumnName("mfa_enabled");e.Property(x=>x.FailedLoginAttempts).HasColumnName("failed_login_attempts");e.Property(x=>x.LockoutUntil).HasColumnName("lockout_until");e.Property(x=>x.LastLoginAt).HasColumnName("last_login_at");e.Property(x=>x.CreatedAt).HasColumnName("created_at");e.Property(x=>x.UpdatedAt).HasColumnName("updated_at");});
        b.Entity<Role>(e=>{e.ToTable("roles","security");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"code",x=>x.Code);Map(e,"name",x=>x.Name);Map(e,"is_active",x=>x.IsActive);});
        b.Entity<UserRole>(e=>{e.ToTable("user_roles","security");e.HasKey(x=>new{x.UserId,x.RoleId});Map(e,"user_id",x=>x.UserId);Map(e,"role_id",x=>x.RoleId);});
        b.Entity<Feature>(e=>{e.ToTable("features","security");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"code",x=>x.Code);Map(e,"name",x=>x.Name);Map(e,"route_path",x=>x.RoutePath);});
        b.Entity<Permission>(e=>{e.ToTable("permissions","security");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"feature_id",x=>x.FeatureId);Map(e,"code",x=>x.Code);Map(e,"name",x=>x.Name);});
        b.Entity<RolePermission>(e=>{e.ToTable("role_permissions","security");e.HasKey(x=>new{x.RoleId,x.PermissionId});Map(e,"role_id",x=>x.RoleId);Map(e,"permission_id",x=>x.PermissionId);});
        b.Entity<UserPermissionOverride>(e=>{e.ToTable("user_permission_overrides","security");e.HasKey(x=>new{x.UserId,x.PermissionId});Map(e,"user_id",x=>x.UserId);Map(e,"permission_id",x=>x.PermissionId);Map(e,"is_allowed",x=>x.IsAllowed);});
        b.Entity<Vendor>(e=>{e.ToTable("vendors","master");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"vendor_code",x=>x.VendorCode);Map(e,"vendor_name",x=>x.VendorName);Map(e,"oracle_vendor_id",x=>x.OracleVendorId);Map(e,"is_active",x=>x.IsActive);});
        b.Entity<VendorUser>(e=>{e.ToTable("vendor_users","master");e.HasKey(x=>new{x.VendorId,x.UserId});Map(e,"vendor_id",x=>x.VendorId);Map(e,"user_id",x=>x.UserId);Map(e,"is_primary",x=>x.IsPrimary);Map(e,"is_active",x=>x.IsActive);});
        b.Entity<PurchaseOrder>(e=>{e.ToTable("purchase_orders","procurement");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"vendor_id",x=>x.VendorId);Map(e,"po_number",x=>x.PoNumber);Map(e,"po_date",x=>x.PoDate);Map(e,"currency_code",x=>x.CurrencyCode);Map(e,"total_amount",x=>x.TotalAmount);Map(e,"remaining_amount",x=>x.RemainingAmount);Map(e,"status",x=>x.Status);});
        b.Entity<Grn>(e=>{e.ToTable("grns","procurement");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"purchase_order_id",x=>x.PurchaseOrderId);Map(e,"grn_number",x=>x.GrnNumber);Map(e,"grn_date",x=>x.GrnDate);Map(e,"status",x=>x.Status);Map(e,"qc_status",x=>x.QcStatus);});
        b.Entity<Invoice>(e=>{e.ToTable("invoices","invoice");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"vendor_id",x=>x.VendorId);Map(e,"invoice_number",x=>x.InvoiceNumber);Map(e,"invoice_date",x=>x.InvoiceDate);Map(e,"invoice_amount",x=>x.InvoiceAmount);Map(e,"currency_code",x=>x.CurrencyCode);Map(e,"po_number",x=>x.PoNumber);Map(e,"grn_numbers",x=>x.GrnNumbers);Map(e,"invoice_type",x=>x.InvoiceType);Map(e,"status",x=>x.Status);Map(e,"integration_status",x=>x.IntegrationStatus);Map(e,"oracle_invoice_id",x=>x.OracleInvoiceId);Map(e,"submission_date",x=>x.SubmissionDate);Map(e,"remarks",x=>x.Remarks);Map(e,"created_by",x=>x.CreatedBy);Map(e,"created_at",x=>x.CreatedAt);Map(e,"updated_at",x=>x.UpdatedAt);Map(e,"deleted_at",x=>x.DeletedAt);});
        b.Entity<InvoiceGrn>(e=>{e.ToTable("invoice_grns","invoice");e.HasKey(x=>new{x.InvoiceId,x.GrnId});Map(e,"invoice_id",x=>x.InvoiceId);Map(e,"grn_id",x=>x.GrnId);});
        b.Entity<Document>(e=>{e.ToTable("documents","invoice");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"invoice_id",x=>x.InvoiceId);Map(e,"document_type",x=>x.DocumentType);Map(e,"original_file_name",x=>x.OriginalFileName);Map(e,"content_type",x=>x.ContentType);Map(e,"file_extension",x=>x.FileExtension);Map(e,"file_size",x=>x.FileSize);Map(e,"file_hash_sha256",x=>x.FileHashSha256);Map(e,"file_content",x=>x.FileContent);Map(e,"uploaded_by",x=>x.UploadedBy);Map(e,"uploaded_at",x=>x.UploadedAt);});
        b.Entity<InvoiceStatusHistory>(e=>{e.ToTable("invoice_status_history","invoice");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"invoice_id",x=>x.InvoiceId);Map(e,"old_status",x=>x.OldStatus);Map(e,"new_status",x=>x.NewStatus);Map(e,"remarks",x=>x.Remarks);Map(e,"source",x=>x.Source);Map(e,"changed_by",x=>x.ChangedBy);Map(e,"changed_at",x=>x.ChangedAt);Map(e,"correlation_id",x=>x.CorrelationId);});
        b.Entity<Payment>(e=>{e.ToTable("payments","payment");e.HasKey(x=>x.Id);Map(e,"id",x=>x.Id);Map(e,"invoice_id",x=>x.InvoiceId);Map(e,"payment_reference",x=>x.PaymentReference);Map(e,"payment_date",x=>x.PaymentDate);Map(e,"amount",x=>x.Amount);Map(e,"status",x=>x.Status);});
    }
    static void Map<T,TProp>(Microsoft.EntityFrameworkCore.Metadata.Builders.EntityTypeBuilder<T> e,string name,System.Linq.Expressions.Expression<Func<T,TProp>> p) where T:class=>e.Property(p).HasColumnName(name);
}
